// ── Builder (Android `DimenPerimeter` / `PerimeterSp`). ───────────────────────────
/** Custom-dimension builder for the perimeter strategy. */
export class DimenPerimeter extends DimenBuilder {
  get prsdp(): number { return this.sdp; }
  get prsdpPx(): number { return this.sdpPx; }
  get prssp(): number { return this.ssp; }
  get prsspPx(): number { return this.sspPx; }
  get prsem(): number { return this.sem; }
  get prsemPx(): number { return this.semPx; }
  get prhdp(): number { return this.hdp; }
  get prhdpPx(): number { return this.hdpPx; }
  get prhsp(): number { return this.hsp; }
  get prhspPx(): number { return this.hspPx; }
  get prhem(): number { return this.hem; }
  get prhemPx(): number { return this.hemPx; }
  get prwdp(): number { return this.wdp; }
  get prwdpPx(): number { return this.wdpPx; }
  get prwsp(): number { return this.wsp; }
  get prwspPx(): number { return this.wspPx; }
  get prwem(): number { return this.wem; }
  get prwemPx(): number { return this.wemPx; }
}
/** Starts a builder: `perimeterDp(16).screen(UiModeType.TELEVISION, 40).prsdp`. */
export const perimeterDp = (value: number): DimenPerimeter => new DimenPerimeter(B, value);
/** Text builder (same class; read `.prssp` / `.prsem`). */
export const perimeterSp = (value: number): DimenPerimeter => new DimenPerimeter(B, value);
